sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
  var choices =[];
  var year = new Date().getFullYear();
  console.log('year ; '+year);
    for (var i = 0; i <= 10; i++) {
        choices.push({
            id : year+i,
            label : year+i
        });

    }

api.setState('yearChoices',choices);

var num =  api.data.record.form.fields.number.displayValue;
console.log("num ; "+num);
api.setState('wbsNumber',num);

}
